"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Рудонун жаңы көрүнүшү: руда тамырлары — кара базальттагы жаркыраган зымырыт кесилген кристаллдар, учкундар жана жашыл туман; экстрактор — алты кырдуу тирөөч, уя куполу жана жашыл маяктуу торчо мунара (тилкеси жана желекчеси — команданын түсү)",
"New in v6.1":"v6.1де жаңы",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefieldдегидей өз классың (U, өлгөндөн кийин сандар): мүмкүн болгондо ошол класстан кайра чыгасың",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Техника биринчи жактан (V — сырттан/кабинадан); жумшак автоприцел — Жөндөөлөрдө",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Өзөктөн чыгуу оңой: Боштук — шахтага, B — жер бетине капсула; жөндөмдөрдүн таасири өлгөндө тазаланат",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Чексиз өнүгүү: генералдар жана Маршал ★, карьера деңгээлдери, куралды өздөштүрүү жана жабдуулар, медалдар, күндөлүк контракттар — «Карьера» экраны",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратегия: колесо менен жылмакай масштабдоо, юниттердин үстүндөгү белгилер жана жазуулар (Alt — баары), сол жакта «Аскерлер / Имараттар» панели",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"оң баскыч — чабуулдуу жылуу, 2× оң баскыч — жүрүп бара атып марш; сейрек буйруктар — «Дагы буйруктар ▾» ичинде; баскычтар кайталанбайт",
"New in v6":"v6да жаңы",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Аткычтардагыдай ок атуу: заматта тийген окторлор, мүнөтүнө 720 ок атуучу автомат, пулемёт, тепки, оң баскыч менен мээлөө, магазиндер жана R менен кайра толтуруу, тийүү белгилери",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Тартылуу оорураак, jetpack тез жооп берет, Z же абада 2× jetpack менен секирик; башка жоокерге өткөндө курал артынан учуп кетпейт",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Курулуш: куруучуну тандагыла, имаратты тандагыла, чийме коюгула; Экстракторлор руда тамырларында; «РУДА» басканда кирешени жана аны көбөйтүүнү көрөсүң",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Боз баскычтар себебин түшүндүрүп, чечим сунуштайт; чоң баскычтар, «Аткарылууда» тилкеси, «▶ Башкаруу», Tab — бир эле режим баскычы",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Секирүүсүз жана оодарылбай турган стратегия камерасы, курсорго масштабдоо, миникартаны сүйрөсө болот",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Жаңы техника: \"Chiyaboʻri\" эмес — «Шакал» рейдери, «Град» ЗРСО (өзү багыттаган ракеталар), «Болга» миномёту; Гала: «Аары», «Уя», «Манжаник»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Стратег буйруктарды тынымсыз өзгөртпөйт жана үн менен спам кылбайт; салгылашуулар жаныңда болот; B — которуу, Shift+B — салгылашуунун ортосуна; компас, H — кайсы максат",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Эркин ойноо (K) жана «жалгыз иштейм» (J), F2 — пресеттер; Esc — тыным жана кайра; сактоолор: слоттор, файлды экспорттоо жана импорттоо",
"New in v5.3":"v5.3төгү жаңылыктар",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Учуу: метеориттен алыс жерде тартылуу күчтүүрөөк, абада C — тормоз, тартуу курчураак рулдайт; порталда «асылып» калбайсың",
"New in v5":"v5 версиясындагы жаңылыктар",
"Endless war by default and battle scale: normal, large, epic":"Демейки боюнча чексиз согуш жана салгылашуу масштабы: кадимки, чоң, эпикалык",
"Save and load the battle (autosave every 3 minutes)":"Салгылашууну сактоо жана жүктөө (жана 3 мүнөт сайын авто сактоо)",
"Squadmates with callsigns: portraits, health and live chatter":"Чакырык белгилүү отряддаштар: портреттер, ден соолук жана жандуу сүйлөшүүлөр",
"Fog of war in strategy, friends and foes outlined differently":"Стратегияда согуш туманы, достор менен душмандар башкача белгиленет",
"Camera fly-over when switching, portal aurora instead of rings":"Которгондо камеранын учуп өтүшү, шакектердин ордуна портал нуру",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Кошумча тапшырмалар, асман аркылуу кыска жол, биринчи экспедициянын запастары бар турак жайлары, кристаллдар, кратерлердеги муз, чаң бороондору",
