"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Граната: G кармап — жаа жана жарылуу тегереги көрүнөт; баскычты бармак менен сүйрөп — бурч; коё берсең — ыргытылат.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Граната: {0} кармап — жаа жана жарылуу тегереги, коё берсең — ыргытылат. Аралык — көрүү бурчу менен, дөңгөлөк — күч, оң баскыч — буттун астына.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Гранаталар: G кармап — учуу жаасы, жарылуу чекити жана тегереги, аралык; коё берсең — ыргытылат. Аралык — көрүү бурчу менен, дөңгөлөк — күч, оң баскыч — буттун астына",
