"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Граната ({0}): кармап — учуу жаасы, жарылуу чекити жана тегереги, аралык; коё берсең — ыргытылат; кыска басуу — дароо ыргытат. Аралык — көрүү бурчу менен, дөңгөлөк — күч, оң баскыч — буттун астына. Телефон: G кармап, бармак менен сүйрө.",
