"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Консорциумдун оор мылтыкчысы эми скелети бар чыныгы 3D-модель: турат, басат, куралы менен чуркайт, жүрүп баратып атат жана талкалангандан кийин сонун жыгылат",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Модель метеориттин бетине нормаль боюнча турат, денесин кароого карай буруп, пулемётту кармап турат; алыста анимация сейрек жаңыртылат — FPS түшпөйт",
