"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Жөө аскер: штурм отряддары, пулемётчулар, снайперлер, чалгынчылар, капсулалар; бронь жана курал жакшыртуулары.",
"Ore depot":"Руда кампасы",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Куруучулар кристаллдарды ушул жерге тапшырат. Кристалл талаасынын жанына тик — жакын ташыйт, руда көп болот.",
"Tanks and vehicles. Requires Barracks.":"Танктар жана техника. Казарма керек.",
