"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Ранец II жана Асман десанты (ранец элитасы). Мех заводу керек, 6:00 өткөндө ачылат.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Өз чекитиңдеги экинчи база: куруучулар, кристалл тапшыруу, толуктоо.",
