"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"Ранецтер менен авиация кийин ачылат — зениттик коргонуу менен турелдерди тигип үлгүр. Азырынча Казарма менен мех заводун кур.",
"Lone heavy gunner":"Жалгыз оор мылтыкчы",
"Crystals nearby are depleted — builder is idle":"Жакынкы кристаллдар бүттү — куруучу бош",
"A crystal field is depleted":"Кристалл талаасы түгөндү",
"carrying ore (+{0})":"маданды ташыйт (+{0})",
"mining crystals":"кристалл казат",
