"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"Кристалл казуу: куруучу жашыл талаадан жүк алып, штабка/кампага ташыйт. Же кристаллдарды RMB менен бас.",
"Gather":"Казуу",
"crystals":"кристаллдар",
"Crystal field here":"Бул жерде кристалл талаасы",
"crystals (carried by builders)":"кристаллдар (куруучулар ташыйт)",
"extractors on veins":"тамырлардагы экстракторлор",
"points":"чекиттер",
"Crystals — carried by builders":"Кристаллдар — куруучулар ташыйт",
"select a builder → RMB a green ◆ field (or \"Gather\", G). Loads of 6 go to the HQ, an outpost or an Ore depot (J). A depot next to the field is faster.":"куруучуну бөлүп көрсөт → жашыл ◆ талааны RMB менен бас (же «Казуу», G). 6 жүк штабка, форпостко же Руда кампасына (J) барат. Талаанын жанындагы кампа — тезирээк.",
"Also: wrecks":"Дагы: сыныктар",
"Two kinds of mining: <b>crystals</b> ◆ — fast but needs builders running loads; an <b>extractor</b> ⛏ on a vein — automatic, slower, can be destroyed. Also: wrecks":"Казуунун эки түрү: <b>кристаллдар</b> ◆ — тез, бирок куруучулар менен каттамдар керек; тамырдагы <b>экстрактор</b> ⛏ — өзү казат, жайыраак, аны жардырса болот. Дагы: сыныктар",
"Select units to toggle \"Autonomous\"":"«Автономдуу» режимин күйгүзүү/өчүрүү үчүн юниттерди бөлүп көрсөт",
"Autonomous ({0}): they act on their own, like under the AI strategist. ⟳ icon above. Press O again for manual.":"Автономдуу ({0}): өз алдынча аракеттенет, AI-стратег башкаргандай. Үстүндө ⟳ белгиси. Кол менен башкаруу үчүн O кайра бас.",
"Manual control ({0}): waiting for your orders":"Кол менен башкаруу ({0}): буйругуңду күтүшөт",
"You are in the fight — all units are autonomous ({0} were manual). In strategy: select and press \"Autonomous\" (O) to take manual control again.":"Сен салгылашып жатасың — бардык юниттер автономдуу ({0} кол менен болчу). Стратегияда: бөлүп көрсөтүп «Автономдуу» (O) бас — кайра кол менен.",
"{0} from the pod awaits orders":"Капсуладан чыккан {0} буйрукту күтөт",
"Select a squad with fewer than 4 troopers":"Курамы толук эмес дастаны танда (4 жоокерден аз)",
"Reinforcing ({0}): at the HQ, an outpost or an owned point, {1} ore per trooper":"Толуктоо ({0}): Штабдын, форпосттун же өз чекитиңдин жанында, жоокерине {1} руда",
"Reinforce":"Толуктоо",
"In strategy squads do not reinforce by themselves (it costs ore). Press — the squad reinforces at the HQ/outpost/owned point, {0} ore per trooper.":"Стратегияда отряддар өзү толукталбайт (руда коротулат). Бас — отряд Штабдын/форпосттун/өз чекитинин жанында толукталат, жоокерине {0} руда.",
"AUTONOMOUS":"АВТОНОМДУУ",
"Mixed":"Аралаш",
"Manual":"Кол менен",
"Acting on their own now. Press (O) to take manual control.":"Азыр өз алдынча аракеттенет. Кол менен башкаруу үчүн O бас.",
"Obeying only you now. Press (O) to let them act on their own, like under the AI strategist.":"Азыр сени гана угат. O бас — AI-стратег башкаргандай өзү аракет кылсын.",
