"send a builder to the green ◆ crystals — RMB them":"куруучуну жашыл кристаллдарга ◆ жөнөт — аларга оң баскыч",
"build Barracks ⚔ with a builder — no infantry without it":"куруучу менен Казарма ⚔ кур — ансыз жөө аскер жок",
