"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Көрүү 190 м, бүт армия үчүн душмандарды белгилейт (160 м), артиллерия менен РСЗО белгиленген аймакты эки эсе тагыраак уруп турат, мунарадагы снайпер жөө аскерлерге атат.",
"Armour plating":"Бронь плиталары",
"HQ +50% HP and −25% damage taken.":"Штаб +50 % бекемдик жана −25 % зыян.",
"Defence turrets":"Коргонуу турелдери",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"Штаб аянтчасында 4 кош турель: жөө аскерлерге, дрондорго, жеңил техникага 95 м чейин.",
"Faster orbital drop":"Ылдамдатылган орбиталык таштоо",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Багыттоочу маяк: казармадан отряддар менен жалгыздар, курууучулар жана капсула 35 % тезирээк даяр болот, капсула 25 % арзандайт.",
