"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Чекиттеги {0} капсула: {1}{2}{3}. Инженер форпост тургузуп (V), жакшыртуу бутагын тандай алат.",
