"Built":"Курулду",
"Building — click to cancel (refund)":"Курулууда — басуу: жокко чыгаруу (руда кайтат)",
"Outpost upgrades":"Форпостту жакшыртуулар",
"point":"чекит",
"Pick a branch — every point gets its own speciality:":"Бутакты танда — ар бир чекиттин өз адистештирүүсү бар:",
"Building — click to cancel":"Курулууда — басуу: жокко чыгаруу",
"A builder near the outpost (30 m) does the upgrade.":"Жакшыртууну форпосттун жанындагы куруучу курат (30 м).",
"Send a builder":"Инженер чакыруу",
"Builders nearby":"Жакын жердеги куруучулар",
"{0} is heading to the outpost":"{0} форпостко баратат",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Согуштун башынан эле базада бүт армия бирден турат: десант, жалгыз пулемётчу, снайпер, чалгынчы, дрон, рейдер, РСЗО, миномёт (жана кол салуучу отряддар менен танк) — дароо каалаганын башкар",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"Башкаруунун «Өз тартиби» (пауза, телефондо ☰): ар бир класстын номери бар, 1 — эң башкысы; ▲▼ өзгөртөт, ✕ — эч качан. Набыт болгондон кийин жана X боюнча ушул тартип менен согушка эң жакын жоокер алынат",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Боттор мындан ары снайпер эмес: алыстан, чуркап бараткан жана жашынган бутага жаңылышат; өтүп бара жаткан октор сени жанынан ышкырып өтүп, жерди жана жакын жердеги жашынуучу жерди урат. Жарылуулар жыгат: селт этүү, тизеге, жыгылып кайра туруу",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Чекитти ээлеп алсаң — капсулада отряд жана куруучу түшөт. Чекиттеги форпост бир бутак боюнча жакшырат: коргонуу (дот → танкка каршы замбиректүү бункер), колдоо (оңдоочу дрондор → күч куполу), чалгын (радиосканер → снайпер мунарасы)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Штаб да жакшырат: бронь плиталары, турелдер, ылдамдатылган орбиталык таштоо, киреше +25 %, глобалдык радар, байланыш антенналары (+командалык упайлар). AI да ушуну эле кылат",
"New in v7.0":"v7.0 жаңылыктары",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"Базада ар бир түрдөн бирден жоокер жана машина бар: десант, снайпер, чалгынчы, дрон, рейдер, РСЗО, миномёт. Каалаганын бөлүп {0} — курулбай туруп сынап көр.",
"POSSESS":"БАШКАРУУ",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"{0} чекити: капсуладан куруучу түштү. Аны бөлүп алып, чекиттин жанына «Форпост»{1} тургуз — андан соң жакшыртуу бутагын тандайсың.",
"OUTPOST":"ФОРПОСТ",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Форпост даяр — аны бөлүп, бутакты танда: ⛨ Коргонуу (дот, танкка каршы замбиректүү бункер), ✚ Колдоо (оңдоочу дрондор, күч куполу) же ◎ Чалгын (сканер, снайпер мунарасы). Жанындагы куруучу курат.",
"UPGRADE":"ЖАКШЫРТУУ",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Штабды «супер-чекит» катары тандаңыз{0} — бронь, турелдер, ылдам таштоо, киреше +25 %, радар, байланыш.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → «Башкаруу»: «Өз тартибим» күйгүзүп, өлгөндөн кийин кимди башкарарыңды танда — №1, №2… ✕ — эч качан.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → пауза → «Өз тартибим»: өлгөндөн кийин жана X боюнча кимди башкарарыңды танда — №1, №2… ✕ — эч качан.",
