"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Жакындатуу үчүн «Мээлөө» баскычын таптап кой. Дагы таптасаң — кайра.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Отряд сени ээрчийт. ☰ → «Тындыруу» → «Отряд мени менен» плиткасын ач — «Жалгыз аракеттенем» болот.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Куруучу тандалды — төмөндөгү карточкасынан «◆ Кристаллдарды казуу» баскычын таптап кой (же жашыл кристаллдарды таптап кой).",
"Training complete!":"Окутуу аяктады!",
"steps":"кадам",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Сен база куруп, аскерлерди буйрук кылып, командалап, салгылашууга секире аласың. Андан ары — чыныгы матч: Куратор оюн учурунда айтып турат.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Сен кыймылдап, учуп, атып, жашынып жана отрядга командалай аласың. Андан ары — чыныгы матч.",
"Real battle":"Чыныгы салгылашуу",
