"Voice of hints & curator":"Кеңештердин жана жетекчинин үнү",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Телефон: стиктин үч режими. Сол гана — «авто» (күчтүү магнит, бирок октор алсыз). Оң гана — прицел өзү күйөт, магнит күчтүү, тактык жакшы. Экөө тең — прицелсиз, магнит жана тактык азыраак. Оң жактагы 👁 баскычы интерфейсти жашырат/кайтарат.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Телефон: стратегия жөнөкөйлөтүлдү — инженер жана имараттар гана. Сол жакта карточкалар (инженер, штаб, казарма…): таптасаңыз — камера ага учат, төмөндө эмне куруу/чыгаруу көрүнөт. «Салгылашууга» — сол жогортодо. Армия өзү салгылашат. Толук стратегия — Жөндөөлөр → Телефон.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Башкаруу — эки белги: «Отряддар» жана «Техника» (телефондо техника демейде өчүк — аны ИИ айдайт). Техника өчүк болсо, өз машинаңдын жанында E (телефондо — оң жактагы баскыч) менен анын замбирегинин артына отурасың: машина өзү жүрөт, сен атасың. Эски «класстардын өз тартиби» — «Кеңейтилгендерде». Башкарганда юнит рация аркылуу жооп берет.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Акылдуу кеңештер: негизги кеңештер 2-жолу ишке киргизгенден кийин өзү өчөт, бирок оюн сен колдонбогон функцияны эскертет. Белгилер: негизги / өркүндөтүлгөн / сейрек, өзүнчө — кеңештердин жана жетекчинин үнү.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Рефлекс өлтүрүүлөрдөн толот (серия — көбүрөөк). Жолдоштор артта калса же набыт болсо — стратег сизге жаңыларын десант кылат (кадимки толуктоодон кымбат). v7.2gfx графикасы жана үнү кошулду: түтүндөгөн жарылуулар, түтүн, сыныктар, шахта жана кратер акустикасы. Курулуш датасы чыныгы.",
