"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Карьера жана сакталгандар өзгөрбөйт. Салгылашууда ушул эле меню — жогорку оң жактагы «🛠 Меню» баскычы{0}.",
"New developer match":"Иштеп чыгуучунун жаңы матчы",
"all unlocked, endless ore, instant build, arsenal":"баары ачык, руда түгөнбөйт, заматта куруу, арсенал",
"Trainings — all 4":"Окутуулар — төртөө тең",
"PC and phone (strategy and shooter)":"ПК жана телефон (стратегия жана атуучу)",
"Cinema: split screen":"Кино: сплит-экран",
"strategist bot left, shooter bot right":"сол жакта бот-стратег, оң жакта бот-атуучу",
"Cinema: everything built":"Кино: бардыгы курулган",
"both bases built and upgraded — for footage":"эки база тең курулуп, өркүндөтүлгөн — тартуу үчүн",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Кино режими — сплит-экран: сол жакта бот-стратег (база менен армияга жогорудан көрүнүш), оң жакта биринчи жактан бот-аткыч. Төмөнкү баскычтар (жана S, P баскычтары): «Сплит-экран» жана «★ Бардыгы курулган» — эки база тең тартуу үчүн курулуп, өркүндөтүлгөн.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Өзөк менен метеорит аркылуу өткөн туннелдер жок болду — метеорит бүтүн, согуш бетинде гана жүрөт.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Телефон: 👁 интерфейсти жашырат, бирок жетпакты, ⇆, стиктерди жана тапшырма белгисин калтырат. «◎ Прицел» (оң манжа гана) — магнит бир кыйла күчтүү жана кененирээк; үч режимдин магниттик күчү — Жөндөөлөр → Башкаруу → «Кеңейтилген». Машинанын замбиреги артында баскыч «Түшүү» деп аталат.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Окутуу: телефондо — телефондук гана, ПКда — ПК гана. Төртөөнүн бардыгы «🛠 Иштеп чыгуучу» менюсунда. Иштеп чыгуучу режими менен Арсенал бир менюга бириктирилди (салышта — оң жактын үстүндөгү «🛠 Меню», ПКда F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"«Dendy (8-бит)» жана «16-бит» графика стилдери: Жөндөөлөр → Графика → «Графика стили» (чоо-жайы — ⚙ баскычы). Матчтын алгачкы ~10 с ичинде FPS 24төн төмөн болсо, Dendy өзү күйөт (20дан төмөн болсо — пиксель дагы ири, 120 сап); «кадимкисине кайтаруу» билдирүүсү кадимки графиканы биротоло кайтарат. Менюдагы тандооң ар дайым биринчи.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Чөйрөнүн 3D моделдери (урандылар, техника, чептер) — жакшы баа алгандары гана, талап боюнча жүктөлөт. Өчүрүү: Жөндөөлөр → Графика → «Чөйрөнүн жаңы 3D моделдери».",
