"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Жоокерлер менен куруу: E (телефондо «Кирүү») өз курулушуңдун жанында — жоокер өзү курат, жакындагы шериктер жардам берет. Инженерлер бош эмес болсо, стратег өзү жардам сурайт — «КУРУЛУШ» белгиси.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Стратегдин белгилери: стратег жаныңдагы душман топторуна ⌖ коёт — 8 с өткөндөн кийин ага артиллерия урат, жакындагы өз РСЗО «Град» залп берет. Стратегия режиминен берген артиллериялык соккуңа да «Град» колдоо көрсөтөт.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Жүк контейнерлериндеги жана кулаган спутниктердеги курал тайниктери (📦 70 м аралыктан көрүнөт): E — 90 с оор пулемёт, өрттөөчү ок-дарылар же ракеталар, плюс толук гранаталар. Сойлоп жүрүү: Ctrl — жатуу / туруу (төмөн, тынч, тагыраак, бирок жай).",
"Anonymous statistics":"Анонимдүү статистика",
"no names or emails: version, device, play time — to make the game better":"аты-жөнсүз жана почтасыз: версия, түзмөк, ойноо убактысы — оюнду жакшыртуу үчүн",
"Anonymous statistics (no names or emails)":"Анонимдүү статистика (аты-жөнсүз жана почтасыз)",
