"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Телефондо үч стик режими, жөнөкөй стратегия, машинанын замбиреги, капчыгайлуу рельеф, отряд класстары, жарылуучу заттар",
"Lite mode, two-stick phone controls":"Жеңил режим, телефондо эки стик менен башкаруу",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"Этап: форпосттор жана штабды жакшыртуу, кинематографиялык мүдүрүлүүлөр, жарылуудан жыгылуу",
