"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Азыр ойноо» — менюнун биринчи баскычы: портал-асман астынан кыска учуу — жана түз салышка (өткөрүп жиберүү — каалаган баскыч же таптоо).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Тийүүлөр сезилет: металл үн жана учкундар, прицелдин жанында өлтүрүү белгиси (башка тийсе — сары), ×N серия, жарылуулардан жылмакай титирөө, маанилүү өлтүрүүлөрдө слоу-мо. Титирөөнү, слоу-монун жана кеңешти Жөндөөлөрдөн өчүрсө болот.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Матч жыйынтыгы: убакыт, жок кылуулар, мыкты серия, ★ MVP жана мыкты отряд, матч картасы — «⇪ Бөлүшүү», PNG же оюнга шилтеме.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Ресурстардын астында сол жакта «азыр эмне кылуу» кеңеши: стратегдин буйругу, ээлей турган чекит, Топтун чабуулу. ✕ же F7 — жыйноо.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Өтмөктү жапсаң же жыйсаң, салыш өзү сакталат — менюда «⟲ Улантуу».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 версиясы «🕘 Оюн версиясы» менюсунда калды — жаңысы жакпаса. Анонимдүү статистика (аты-жөнсүз жана почтасыз) эми жөнөтүлөт; өчүрүү — Жөндөөлөрдө.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Азыр ойноо», тийүү сезими, матч жыйынтыгы карта менен, «эмне кылуу» кеңеши, автосактоо",
"and older: v7.5, v7.4, milestones v1–v7.0":"жана эскилер: v7.5, v7.4, v1–v7.0 бекем этаптары",
"New in v7.6":"v7.6да жаңы",
"NEW IN v7.6":"v7.6да ЖАҢЫЛЫКТАР",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Матчтын алдында фракцияны тандоо: «Консорциум» (күч сауттагы оор жөө аскер, бронь жана артиллерия) же «Үймө» (ылдамдык, дрон топтору, бурмалоо менен оор ок атуулар). AI башкасын ойнойт. Тандоо эсте калат.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Ар бир фракциянын өз техникасы жана өзгөчөлүгү бар: Консорциумда — «Каркидан» танкы жана «Керамит плиталар», Үймөдө — «Дрон тобу» жана «Фазалык ранецтер». Баланс бот матчтары менен текшерилди.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Жарылуу чуңкурлары: артиллерия, ракеталар жана танктардын замбиректери метеоритке чуңкур казат — алардын ичи менен басып, жүрүп өтсө болот, алардын ичине жашынууга болот.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Жоокер үчүн 3-жактан көрүнүш (V, эсте калат; телефондо — Башкаруу) жана замбирек тиере жерди көрсөткөн белгиси бар жылмакай техника камерасы.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 версиясы «🕘 Оюндун версиясы» менюсунда калды — жаңысы жакпаса.",
