"Pause: resume, restart, training, graphics, settings, main menu":"Тыныгуу: улантуу, кайра баштоо, окутуу, графика, жөндөөлөр, башкы меню",
"Menu: pause, restart, training, graphics, settings":"Меню: тыныгуу, кайра баштоо, окутуу, графика, жөндөөлөр",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Манжаңды жерге ~0,3 с кармап тур — телефон титиреп, сары шакек пайда болот — анан, көтөрбөстөн, сүйрө: алкак чыгат. Же оң жактагы «Алкак» баскычы. Отрядды жөн эле таптасаң да болот.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhoneдо толук экран үчүн: «Бөлүшүү» ⬆ → «Башкы экранга кошуу» — оюн Safari панелдеринсиз ачылат.",
"Open portal-meteor.pages.dev for that.":"Ал үчүн portal-meteor.pages.dev сайтын ач.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Таптоо — тандоо · жерди таптоо — баруу · кармап туруу — буйрук менюсу · кармап сүйрөө — алкак · 2 манжа — масштаб",
"Robo-ninja":"Робо-ниндзя",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Каармандуу өлтүргүч кыз: ыргып өтүүчү телепорттор, катана, сюрикендер. Өзү душмандын зоналары аркылуу секирип, роботторду кыркат. Бир тарапка 1.",
"Shadow protocol":"«Көлөкө» протоколу",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Изилдөө: Казармада робо-ниндзяны ачат. Даяр Мех заводу керек.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Каармандуу кыз (бир тарапка 1): өзү душмандын зоналарына телепортко түшүп, роботторду кыркат; Башкарууга алып кол менен ойносо болот.",
"is ready. She works on her own (AUTO) — possess her to play manually":"даяр. Өзү иштейт (АВТО) — кол менен ойноо үчүн Башкарууга ал",
"Robo-ninja ready for action":"Робо-ниндзя салгылашууга даяр",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Чалгын: душманда робо-ниндзя пайда болду!",
"Warning! The enemy has a robo-ninja. Stay together":"Көңүл бургула! Душманда робо-ниндзя бар. Бирге болгула",
"cyber blinks":"кибер-секирүүлөр",
"Too far for a dash — get closer or teleport":"Секирик үчүн алыс — жакындап бар же телепорт",
"point ":"чекит ",
"enemy group":"душман тобу",
"order":"буйрук",
"nearby":"жакын",
"Zone cleared":"Зона тазаланды",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ НИНДЗЯ ДУЭЛИ! Сокку алдында блок — парирлөө, секирик — качуу. Соккунун жаркылына көз сал",
"The two ninjas have met in a duel!":"Эки ниндзя дуэлде беттешти!",
"⚔ Duel won! Our ninja prevails":"⚔ Дуэль жеңилди! Биздин ниндзя күчтүүрөөк",
"⚔ Duel lost…":"⚔ Дуэль утулду…",
"ninja duel":"ниндзя дуэли",
"POSTURE BROKEN":"ТЕҢ САЛМАК БУЗУЛДУ",
"Teleport":"Телепорт",
"Teleport: aim at the ground (up to 150 m)":"Телепорт: кароону жерге багытта (150 мге чейин)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ АВТО: өзү душмандын зоналарына секирип, кыркат. Джойстик / WASD — 1.5 с тыныгуу",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Кол менен: душманды таптоо — секирип чабуу, серпүү — чабуу, 🛡 — блок",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Кол менен башкаруу: сол баскыч — катана, оң баскыч — блок, Shift — секирик, Q — сюрикендер, G — телепорт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ниндзя: душмандын үстүнө таптоо — секирип чабуу, оңдон серпүү — чабуу, ● — сокку, 🛡 — блок (убагында = парирлөө), ⇑ — секирик, ✦ — сюрикендер, ◎ — телепорт, АВТО — өзү",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ниндзя: сол баскыч — катана (кармап туруу — оор сокку), оң баскыч — блок (убагында = парирлөө), Shift/Z — секирик, Q — сюрикендер, G — нишанга телепорт, абада секирүү — кош секирүү / дубал боюнча чуркоо, {0} — АВТО",
