"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor радиосу: EDMITRY'дин 100+ трегин оюндун ичинде — 📻 баскычы (ПК: 5 баскычы, [ ] — трек). Музыка тармак аркылуу жүктөлөт, оюнду оорлотпойт; үн деңгээли жана автоишке киргизүү Жөндөөлөрдө, «Spotify'да угуу» шилтемеси бар.",
