"Radio":"Радио",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Portal Meteor радиосу күй/өч ([ ] — трек, Shift+[ ] — үн)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 оң жакта — Portal Meteor радиосу: салгылашып жатканда EDMITRY музыкасы.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor радиосу: салгылашып жатканда EDMITRY музыкасы. [ ] — трек.",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor радиосу (EDMITRY): үн деңгээли",
"Radio: start by itself in battle":"Радио: салгылашта өзү күйсүн",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Робо-ниндзя: катана кармаган киборг. Казармада «Көлөкө протоколу» изилдөөсү менен ачылат (Мех заводу керек). Өзү душмандын зоналарына телепорттолот, душмандарды бөлүп чабат (кан жок — учкундар), секирүүлөр, сюрикендер, душмандын ниндзясы менен дуэлдер. Ага Башкаруу — АВТО режими же кол менен башкаруу (телефондо өз баскычтары бар).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor радиосу: EDMITRY'дин 103 трегин оюндун ичинде. 5 баскычы (кайра дайындалат), телефондо — ☰ → Жөндөөлөр → Үн. Үн деңгээли жана «салгылашта өзү күйсүн» — жөндөөлөрдө; жарылууларда жана рация үнүнүн астында музыка акырыныраак болот.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Жаңы тилдер: өзбек жана тажик — толугу менен; кытай, испан, португал — жарым-жартылай. Менюда «Жаңы матч» жанында жаңы тил тандоосу.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Телефон: «белгилерди жашыруу» 👁 калган баскычтарды оң четтеги иреттүү тилкеге чогултат; портрет мындан ары бири-бирин жаппайт; iPhone — оюн Safari жесттери менен кагылышпайт, ал эми «Бөлүшүү → Башкы экранга кошуу» аны толук экранга ачат.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1ден: бурчтагы ☰ меню (тыным, кайра баштоо, окутуу, графика), авто-Dendy жок, телефондо ✋ аракет баскычы. v7.8.1 жана v7.8 «🕘 Оюндун версиясы» менюсунда калды.",
