"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Өзүңкүлөр жардам сурап, сыйлашат, баатырлар квест берет, созулган фронт операция менен бузулат",
"A request":"Өзүңкүлөрдүн суроосу",
"Breakthrough":"Салгылашуунун бурулушу",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Өзүңкүлөр кээде жардам сурайт: радиодо үн, «СУРАНЫЧ» карточкасы жана ✋ белгиси. Отрядды кысып салышкан — анын жанындагы душмандарды жок кыл. Сыйлык: базадан капсула менен жоокер, багги арткы бөлүгүнөн замбирек, аткыч орду же орбитадан жабуу. Кааламасаң — ✕ же жөн эле көңүл бурба.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ардагер чалгынчы «Үкү» квест сунуштайт. Y — кабыл алуу (N — баш тартуу). ★ белгисине бар, күзөтчүлөрдү жок кыл да, учкучтун жанында 3 с тур — ал сенин отрядыңа кошулат.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Фронт токтоду — штаб бурулуш сунуштайт. Y — кабыл алуу. Ретрансляторду жанында душмансыз 8 с кармап тур: душмандын картасы 60 с көрүнөт. Генератор — душмандын турелдери 2 мүн унчукпайт. Стратегде — «Отрядга берүү». Душман да муну кыла алат: ⚠ карап тур.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Өзүңкүлөр жардам сурайт: «СУРАНЫЧ» карточкасы жана ✋ белгиси. Кысылган отряддын жанындагы душмандарды жок кыл — сыйлык аласың. ✕ — өткөрүп жиберүү.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"«Үкү» баатыры квест сунуштайт — «Кабыл алуу» баскычын бас. ★ барып, күзөтчүлөрдү жок кыл, учкучтун жанында тур.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Фронт токтоду — «Кабыл алууну» таптап, ретрансляторду 8 с кармап тур: душмандын картасы бир мүнөткө ачылат.",
