"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Алсыз жери — арткы бөлүгү (кыймылдаткыч): зыян ×{0}. Замбирек, 2 пулемет мунарасы, ракета кассетасы; өтө жай бурулат — капталынан өтүңөр.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Алсыз жери — курсак астындагы жаркыраган өзөк: ылдыйдан зыян ×{0}. Бурмалоо нуру жана аянт боюнча тебелөө; тосмолордон аттап өтөт — аралыкты сактагыла, топтолбогула.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Каршы: авиабомбалар жана артиллерия (×{0}), ракеталар (×{1}), килем бомбалоо; октор дээрлик пайдасыз (×{2}).",
"Faction":"Фракция",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Ылдам машиналар, дрон топтору, туннелдер жана калыбына келүү. Жөө аскер жеңил, бирок ылдам; замбиректер жана рельсалар катуураак урат.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Күч бронудагы оор жөө аскер, бетон тосмолор, оңдоо жана артиллерия. Жайыраак, бирок бекемирээк.",
