"Discharge: an explosion or a thrown bolt (E / \"Bolt\") — it sleeps 20–35 s, sometimes leaves an artifact.":"Разряддоо: жарылуу же ыргытылган болт (E / «Болт») — 20–35 с уктайт, кээде артефакт калтырат.",
