"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Жогортон карап, бүт армияны башкарасың: базаны куруп, отряддарды жөнөтөсүң. Армия сенсиз да өзү салгылашат.",
"You lead one squad: the camera is above it, tap the ground to move.":"Бир отрядды жетектейсиң: камера анын үстүндө, жерге таптоо — кайда баруу керек.",
